 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid vertical separator between the two equal-width panels.
    split = next(c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and c * 2 + 1 == w)
    panel_w = split
    left = [row[:panel_w] for row in grid]
    right = [row[split + 1:] for row in grid]

    def background(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    right_bg = background(right)
    left_bg = background(left)
    out = [[right_bg for _ in range(panel_w)] for _ in range(h)]
    for r in range(h):
        for c in range(panel_w):
            if left[r][c] != left_bg and right[r][c] == right_bg:
                out[r][c] = 3
    return out
